	var t int64
	fmt.Fscan(in, &n, &sx, &sy, &dx0, &dy0, &t)

	if t == 0 {
		fmt.Println(sx, sy)
		return
	}

	// Precompute constants
	n2 := n * n
	n3 := n2 * n

	// S(t) = sum_{i=0}^{t-1} (x_i + y_i) + t*(t-1)/2
	// x_i = sx + dx0*i + n*i*(i-1)/2
	// y_i = sy + dy0*i + n*i*(i-1)/2

	// Sum x_i
	// sum i = t(t-1)/2
	// sum i(i-1)/2 = (t-1)t(t-2)/6
	sumI := t * (t - 1) / 2
	sumIIm1Over2 := (t - 1) * t * (t - 2) / 6

	sumX := sx*t + dx0*sumI + n*sumIIm1Over2
	sumY := sy*t + dy0*sumI + n*sumIIm1Over2

	// Sum (x_i + y_i)
	sumXY := sumX + sumY

	// Sum of extra bushes: t*(t-1)/2
	sumExtra := sumI

	S := sumXY + sumExtra

	// dx_t = dx0 + S
	// dy_t = dy0 + S
	dxT := dx0 + S
	dyT := dy0 + S

	// x_t = sx + dx0*t + n*t(t-1)/2
	xT := sx + dx0*t + n*sumI
	yT := sy + dy0*t + n*sumI

	// final position with modulo
	xFinal := mod(xT-1, n) + 1
	yFinal := mod(yT-1, n) + 1

	// dxT, dyT not needed for output, only position
	fmt.Println(xFinal, yFinal)
}

