	// dx_t = dx0 + t*(sx+sy) + t*(t-1)/2*(2 + n)
	// dy_t = dy0 + t*(sx+sy) + t*(t-1)/2*(2 + n)
	// Sx_t = t*sx + t*(t-1)/2*(dx0 + sx + sy) + (t-1)*t*(2*t-1)/6 + (t-1)*t*(t-2)/6*n
	// Sy_t same as Sx_t with sy

	// Compute dx_t, dy_t modulo n
	// term1 = t*(sx+sy)
	term1 := (t % n) * ((sx + sy) % n) % n
	// term2 = t*(t-1)/2*(2 + n)
	tt1 := t * (t - 1) / 2
	term2 := (tt1 % n) * ((2 + n) % n) % n
	dx_t := (dx0%n + term1 + term2) % n
	dy_t := (dy0%n + term1 + term2) % n

	// Compute Sx_t, Sy_t modulo n
	// A = t*sx
	A := (t % n) * (sx % n) % n
	// B = t*(t-1)/2*(dx0 + sx + sy)
	B := (tt1 % n) * ((dx0 + sx + sy) % n) % n
	// C = (t-1)*t*(2*t-1)/6
	Cnum := (t - 1) * t * (2*t - 1)
	C := (Cnum / 6) % n
	// D = (t-1)*t*(t-2)/6 * n
	Dnum := (t - 1) * t * (t - 2)
	// D * n mod n is 0, so ignore D in modulo n
	Sx_t := (A + B + C) % n
	// For Sy_t, replace sx with sy in A and B
	Ay := (t % n) * (sy % n) % n
	By := (tt1 % n) * ((dy0 + sx + sy) % n) % n
	Sy_t := (Ay + By + C) % n

	// Final position:
	// x_t = ((sx + Sx_t + dx_t - 1) mod n) + 1
	// y_t = ((sy + Sy_t + dy_t - 1) mod n) + 1
	x := mod(sx+Sx_t+dx_t-1, n) + 1
	y := mod(sy+Sy_t+dy_t-1, n) + 1

	fmt.Println(x, y)
}

