import (
	"bufio"
	"fmt"
	"os"
)

func mod(a, n int64) int64 {
	a %= n
	if a < 0 {
		a += n
	}
	return a
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, sx, sy int64
	var dx, dy int64
	var t int64
	fmt.Fscan(in, &n, &sx, &sy, &dx, &dy, &t)

	// Precompute constants
	// k_i = (sx + sy) + (i-1) + n*(i-1)
	// dx_i = dx + k_i, dy_i = dy + k_i
	// x_{i+1} = ((x_i + dx_i - 1) mod n) + 1
	// y_{i+1} = ((y_i + dy_i - 1) mod n) + 1
	// Simplify:
	// x_{i+1} = (x_i + dx + sx + sy -1 + (i-1)*(1+n)) mod n +1
	// y_{i+1} similar

	A := dx + sx + sy - 1
	B := dy + sx + sy - 1
	C := 1 + n

	// Reduce coefficients modulo n
	Amod := mod(A, n)
	Bmod := mod(B, n)
	Cmod := mod(C, n)

	// x_i = ((sx-1) + i*Amod + (i*(i-1)/2)*Cmod) mod n +1
	// y_i = ((sy-1) + i*Bmod + (i*(i-1)/2)*Cmod) mod n +1

	i := t // step count

	// compute i mod n and i*(i-1)/2 mod n safely
	imod := mod(i, n)
	// i*(i-1)/2 mod n
	// handle division by 2 via modular arithmetic:
	// since n can be even, we compute using 128-bit via big.Int not available; instead:
	// we compute (i mod (2n))*(i-1 mod (2n))/2 then mod n
	// but 2n may overflow int64; use decomposition:
	// use property: (i*(i-1)/2) mod n = ((i mod (2n))*(i-1 mod (2n))/2) mod n
	// with 2n up to 2e9, fits int64.

	twoN := n * 2
	imod2 := i % twoN
	im1mod2 := (i - 1) % twoN
	if imod2 < 0 {
		imod2 += twoN
	}
	if im1mod2 < 0 {
		im1mod2 += twoN
	}
	tmp := (imod2 * im1mod2) / 2
	halfMod := tmp % n

	x0 := sx - 1
	y0 := sy - 1

	x := mod(x0+imod*Amod+halfMod*Cmod, n) + 1
	y := mod(y0+imod*Bmod+halfMod*Cmod, n) + 1

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintf(out, "%d %d\n", x, y)
	out.Flush()
}
